import {
  type VNode,
  type VNodeChild,
  currentBlock,
  isBlockTreeEnabled,
} from '../vnode'
import {
  EffectFlags,
  isReactive,
  ReactiveFlags,
  shallowReadArray,
  toReactive,
} from '@vue/reactivity'
import { hasChanged, isArray, isObject, isString } from '@vue/shared'
import { warn } from '../warning'
import { currentRenderingInstance } from '../componentRenderContext'

export class RenderListContext {
  cached: VNode[] | undefined

  constructor(cached?: VNode[] | undefined) {
    this.cached = cached
  }

  isMemoSame(cached: VNode, memo: any[]): boolean {
    const prev: any[] = cached.memo!
    if (prev.length != memo.length) {
      return false
    }

    for (let i = 0; i < prev.length; i++) {
      if (hasChanged(prev[i], memo[i])) {
        return false
      }
    }

    // make sure to let parent block track it when returning cached
    if (isBlockTreeEnabled > 0 && currentBlock) {
      currentBlock.push(cached)
    }
    return true
  }

  render(
    source: any,
    renderItem: (...args: any[]) => VNodeChild,
    cache?: any[],
    index?: number,
  ): VNodeChild[] {
    let ret: VNodeChild[]
    const cached = this.cached
    const sourceIsArray = isArray(source)

    if (sourceIsArray || isString(source)) {
      const sourceReactive = !!(source && source[ReactiveFlags.IS_REACTIVE])
      const sourceRaw = source && source[ReactiveFlags.RAW]
      let allowWrap = true
      const sourceIsReactiveArray = sourceIsArray && isReactive(source)
      const instance = currentRenderingInstance
      if (instance) {
        const effect = instance.effect
        const scope = instance.scope
        if (effect) {
          allowWrap = allowWrap && typeof effect.fn === 'function'
          allowWrap =
            allowWrap &&
            (effect.flags & (EffectFlags.ACTIVE | EffectFlags.RUNNING)) !== 0
          const link = effect.deps
          if (link) {
            allowWrap = allowWrap && link.version > -2
            const dep = link.dep
            if (dep) {
              allowWrap = allowWrap && dep.version >= 0
              const subs = dep.subs
              allowWrap = allowWrap && (subs == null || link.version > -2)
            }
          }
        }
        if (scope) {
          const detached = scope.detached
          const parent = scope.parent
          allowWrap = allowWrap && (detached || parent != null)
        }
      }
      if (sourceIsReactiveArray) {
        const canWrapProxy = sourceRaw != null || sourceReactive
        allowWrap = allowWrap && canWrapProxy
        source = shallowReadArray(source)
      }
      ret = new Array(source.length)
      for (let i = 0, l = source.length; i < l; i++) {
        ret[i] = renderItem(
          sourceIsReactiveArray && allowWrap
            ? toReactive(source[i])
            : source[i],
          i,
          undefined,
          cached && cached[i],
        )
      }
    } else if (typeof source === 'number') {
      if (__DEV__ && !Number.isInteger(source)) {
        warn(`The v-for range expect an integer value but got ${source}.`)
      }
      ret = new Array(source)
      for (let i = 0; i < source; i++) {
        ret[i] = renderItem(i + 1, i, undefined, cached && cached[i])
      }
    } else if (isObject(source)) {
      if (source[Symbol.iterator as any]) {
        ret = Array.from(source as Iterable<any>, (item, i) =>
          renderItem(item, i, undefined, cached && cached[i]),
        )
      } else {
        const keys = Object.keys(source)
        ret = new Array(keys.length)
        for (let i = 0, l = keys.length; i < l; i++) {
          const key = keys[i]
          ret[i] = renderItem(source[key], key, i, cached && cached[i])
        }
      }
    } else {
      ret = []
    }

    if (cache) {
      cache[index!] = ret
    }
    return ret
  }
}

/**
 * v-for string
 * @private
 */
export function renderList(
  source: string,
  renderItem: (value: string, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for number
 */
export function renderList(
  source: number,
  renderItem: (value: number, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for array
 */
export function renderList<T>(
  source: T[],
  renderItem: (value: T, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for iterable
 */
export function renderList<T>(
  source: Iterable<T>,
  renderItem: (value: T, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for object
 */
export function renderList<T>(
  source: T,
  renderItem: <K extends keyof T>(
    value: T[K],
    key: string,
    index: number,
  ) => VNodeChild,
): VNodeChild[]

/**
 * Actual implementation
 */
export function renderList(
  source: any,
  renderItem: (...args: any[]) => VNodeChild,
  cache?: any[],
  index?: number,
): VNodeChild[] {
  const cached = (cache && cache[index!]) as VNode[] | undefined
  return new RenderListContext(cached).render(source, renderItem, cache, index)
}

